<?php
declare(strict_types=1);require_once __DIR__.'/auth_check.php';require_once __DIR__.'/bootstrap.php';$pdo=app_database();if(!isset($_SESSION['admin_chat_csrf']))$_SESSION['admin_chat_csrf']=bin2hex(random_bytes(24));$conversations=$pdo->query("SELECT c.*,p.designation,(SELECT message FROM messages_boutique m WHERE m.conversation_id=c.id ORDER BY m.id DESC LIMIT 1) dernier_message,(SELECT COUNT(*) FROM messages_boutique m WHERE m.conversation_id=c.id AND m.expediteur='visiteur' AND m.lu_at IS NULL) non_lus FROM conversations_boutique c LEFT JOIN produit p ON p.id_produit=c.produit_id ORDER BY c.updated_at DESC")->fetchAll(PDO::FETCH_ASSOC);function mch(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages boutique | FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><link rel="stylesheet" href="css/admin-chat.css"></head><body class="module-page messaging-page"><?php include __DIR__.'/partials/navbar.php';?><main class="container"><div class="module-heading"><div class="module-heading__copy"><span class="module-heading__icon"><i class="fa-solid fa-comments"></i></span><div><h1>Messages boutique</h1><p>Répondez aux visiteurs, partagez des documents et conseillez-les en direct.</p></div></div></div><section class="messaging-shell"><aside class="conversation-list"><h2>Conversations</h2><?php foreach($conversations as$c):?><button class="conversation-item" data-conversation="<?=$c['id']?>" data-name="<?=mch($c['nom_visiteur']?:'Visiteur')?>" data-product="<?=mch($c['designation']?:'Discussion générale')?>"><?php if($c['non_lus']):?><b><?=$c['non_lus']?></b><?php endif?><strong><?=mch($c['nom_visiteur']?:'Visiteur')?></strong><span><?=mch($c['dernier_message']?:'Fichier ou nouvelle conversation')?></span><small><?=mch($c['designation']?:date('d/m/Y H:i',strtotime($c['updated_at'])))?></small></button><?php endforeach?></aside><section class="admin-chat"><header class="admin-chat-head" id="adminChatHead" hidden><strong id="adminChatName"></strong><small id="adminChatProduct"></small></header><div class="admin-chat-messages" id="adminChatMessages"><div class="chat-placeholder"><i class="fa-regular fa-comments fa-2x mb-2"></i>Sélectionnez une conversation.</div></div><form class="admin-compose" id="adminChatForm" hidden><input type="file" id="adminChatFile" accept="image/jpeg,image/png,image/webp,application/pdf,.doc,.docx,.xls,.xlsx" hidden><button class="admin-attach" id="adminAttach" type="button" title="Joindre un fichier"><i class="fa-solid fa-paperclip"></i></button><textarea id="adminChatInput" rows="2" maxlength="1500" placeholder="Votre réponse…"></textarea><button class="admin-send" type="submit"><i class="fa-solid fa-paper-plane"></i></button><div class="admin-file-status" id="adminFileStatus"></div></form></section></section></main><script>window.FIDEST_ADMIN_CHAT={csrf:<?=json_encode($_SESSION['admin_chat_csrf'])?>,requested:<?=(int)($_GET['conversation']??0)?>};</script><script src="js/admin-chat.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script></body></html>
